{"command":"python3 << 'EOF'
import csv

# Read output and verify
with open('outputs/t06_stop_service_intensity.csv', 'r') as f:
    reader = csv.DictReader(f)
    output_rows = list(reader)

# Verify each row
errors = []
with open('outputs/t05_clean_stops.csv', 'r') as f:
    reader = csv.DictReader(f)
    stops = {row['stop_id']: row for row in reader}

with open('inputs/gtfs/trips.txt', 'r') as f:
    reader = csv.DictReader(f)
    trips = {row['trip_id']: row['route_id'] for row in reader}

with open('outputs/t05_clean_stop_times.csv', 'r') as f:
    reader = csv.DictReader(f)
    stop_data = {}
    for row in reader:
        stop_id = row['stop_id']
        if stop_id not in stop_data:
            stop_data[stop_id] = []
        stop_data[stop_id].append({
            'departure_time': row['departure_time'],
            'route_id': trips.get(row['trip_id'])
        })

for stop_id in sorted(stop_data.keys()):
    stop_info = stop_data[stop_id]

    n_departures = len(stop_info)
    n_routes = len(set(d['route_id'] for d in stop_info if d['route_id']))

    if stop_info:
        departure_times = [d['departure_time'] for d in stop_info]
        first_departure = min(departure_times)
        last_departure = max(departure_times)
    else:
        first_departure = ''
        last_departure = ''

    # Find the output row for this stop
    output_row = next((r for r in output_rows if r['stop_id'] == stop_id), None)
    if output_row:
        if output_row['n_departures'] != n_departures:
            errors.append(f"Stop {stop_id}: n_departures mismatch {output_row['n_departures']} vs {n_departures}")
        if output_row['n_routes'] != n_routes:
            errors.append(f"Stop {stop_id}: n_routes mismatch {output_row['n_routes']} vs {n_routes}")
        if output_row['first_departure'] != first_departure:
            errors.append(f"Stop {stop_id}: first_departure mismatch {output_row['first_departure']} vs {first_departure}")
        if output_row['last_departure'] != last_departure:
            errors.append(f"Stop {stop_id}: last_departure mismatch {output_row['last_departure']} vs {last_departure}")

if errors:
    print("ERRORS FOUND:")
    for e in errors[:10]:
        print(e)
else:
    print("All verifications passed!")
EOF"}

